  "legal.privacy.paymentDataIsTheOneExceptionDodoPaymentsSellsToYouAsMerc": ". ข้อมูลการชำระเงินเป็นข้อยกเว้น: Dodo Payments ขายให้คุณในฐานะ merchant of record และตัดสินใจวิธีประมวลผลข้อมูลนั้น ดู section 4.1",
  "legal.privacy.tahaAalamASoleProprietorTradingAsSophionosIsTheControlle": "Taha Aalam เจ้าของธุรกิจส่วนบุคคลที่ค้าขายภายใต้ชื่อ SophionOS เป็นผู้ควบคุมการประมวลผลที่ระบุใน Policy นี้ ติดต่อ:",
  "legal.privacy.controller": "ผู้ควบคุมข้อมูล",
  "legal.privacy.thisSectionAppliesToYouIfYouAreInTheEuropeanEconomicArea": "ส่วนนี้มีผลกับคุณหากคุณอยู่ใน European Economic Area สหราชอาณาจักร หรือสวิตเซอร์แลนด์ (เรียกรวมว่า \"Europe\") \"Personal information\" ที่นี่หมายถึง \"personal data\" ตามที่กำหนดโดย EU GDPR หรือ UK GDPR Service ไม่ได้จัดตั้งในยุโรป ประกาศนี้กล่าวถึงกฎหมายคุ้มครองข้อมูลของยุโรปตามที่ใช้บังคับกับการเสนอ Service แก่บุคคลในยุโรป",
  "legal.privacy.scope": "ขอบเขต",
  "legal.privacy.n12NoticeToEuropeanUsers": "12. การแจ้งให้ผู้ใช้ในยุโรปทราบ",
  "legal.privacy.weOperateTheServiceFromTheUnitedStatesAndUseServiceProvi": "เราดำเนินงาน Service จากสหรัฐอเมริกาและใช้ผู้ให้บริการในสหรัฐอเมริกาและสหภาพยุโรป ข้อมูลส่วนบุคคลของคุณจึงอาจได้รับการประมวลผลนอกประเทศที่คุณพำนัก รวมถึงในประเทศที่มีกฎหมายความเป็นส่วนตัวแตกต่างจากของคุณ เมื่อ GDPR มีผลบังคับใช้ เราอาศัยมาตรการปกป้องที่เหมาะสมสำหรับการถ่ายโอนเหล่านี้: standard contractual clauses หรือความตกลงว่าด้วยความเพียงพอที่ใช้บังคับ เมื่อ DPDP Act ของอินเดียมีผลบังคับใช้ การถ่ายโอนอยู่ภายใต้ข้อจำกัดที่ Central Government กำหนดภายใต้ Rule 15 ของ DPDP Rules, 2025",
  "legal.privacy.n11InternationalDataTransfers": "11. การถ่ายโอนข้อมูลระหว่างประเทศ",
  "legal.privacy.forTheFullStatementOfWhatTheSoftwareDoesAndDoesNotClaim": "สำหรับถ้อยแถลงฉบับเต็มว่าซอฟต์แวร์ทำอะไรและไม่ได้อ้างอะไร",
  "legal.privacy.noSystemIsPerfectlySecureSophionosIsSelfhostedWhoeverOpe": "ไม่มีระบบใดปลอดภัยสมบูรณ์ SophionOS เป็นแบบโฮสต์เอง ผู้ใดดำเนินการอินสแตนซ์ย่อมรับผิดชอบในการรักษาความปลอดภัยและการปฏิบัติตามหน้าที่แจ้งการละเมิดที่ใช้บังคับกับผู้นั้น ดู",
  "legal.privacy.weEncryptSensitiveFieldsAtTheApplicationLayerBeforeTheyR": "เราเข้ารหัสฟิลด์ที่ละเอียดอ่อนที่ชั้นแอปพลิเคชันก่อนถึงฐานข้อมูล และใช้นโยบายฐานข้อมูลระดับแถวเป็นขอบเขตการแยกหลัก เราเก็บคีย์ API เป็นแฮชเท่านั้น และไม่เก็บบันทึกความยินยอมหรือหลักฐานความยินยอม เนื่องจากการยอมรับคือการใช้ Service เอง (section 2) การเข้าถึงข้อมูลการผลิตโดยพนักงานมีจำกัด มีการบันทึก และได้รับการตรวจสอบ",
  "legal.privacy.n10Security": "10. ความปลอดภัย",
