  "legal.privacy.ifYouBelieveAChildUnder18HasCreatedAnAccountOrProvidedPe": "หากคุณเชื่อว่าเด็กอายุต่ำกว่า 18 ปีสร้างบัญชีหรือให้ข้อมูลส่วนตัว โปรดติดต่อ grievance officer เราจะลบข้อมูลนั้นเมื่อตรวจสอบแล้ว และจะไม่เก็บระหว่างการสืบสวนคำร้อง ยกเว้นเฉพาะสิ่งที่จำเป็นในการตรวจสอบรายงาน",
  "legal.privacy.theServiceIsForPeople18AndOverSoWeDoNotAskForAnAgeDeclar": "Service สำหรับบุคคลอายุ 18 ปีขึ้นไป ดังนั้นเราจึงไม่ขอการระบุอายุและไม่บันทึกอายุ เราไม่ขอความยินยอมจากผู้ปกครองที่ตรวจสอบได้ เนื่องจากเราไม่ประมวลผลข้อมูลส่วนตัวของเด็ก หากทราบว่ามีการประมวลผล เราจะลบข้อมูลนั้น",
