  "legal.terms.continuingToUseTheServiceAfterTheEffectiveDateOfARevised": "การใช้ Service ต่อไปหลังวันที่มีผลของเวอร์ชันที่แก้ไข หมายความว่าคุณยอมรับ การใช้เวอร์ชันเก่าที่เคยยอมรับต่อไปไม่ได้รับอนุญาตหากการเปลี่ยนแปลงเป็นสิ่งที่กฎหมายกำหนดหรือจำเป็นเพื่อแก้ความเสี่ยงด้านความปลอดภัย เวอร์ชันที่มีผลบังคับใช้เมื่อคุณยอมรับ Terms เป็นตัวควบคุมช่วงก่อนหน้านั้น",
  "legal.terms.whenWePublishAVersionThatChangesTheseTermsMateriallyUser": "เมื่อเราเผยแพร่เวอร์ชันที่เปลี่ยนแปลง Terms เหล่านี้สาระสำคัญ ผู้ใช้ที่อยู่ในเวอร์ชันเก่าจะเห็นประกาศขอให้ตรวจสอบและยอมรับเวอร์ชันใหม่ก่อนใช้ Service ต่อไป บันทึกความยินยอมของคุณต่อแต่ละเวอร์ชันถูกเก็บรักษาไว้ ดังนั้นคุณดูได้ว่ายอมรับเวอร์ชันใดและเมื่อใด",
  "legal.terms.withItsOwnVersionNumberAndEffectiveDate": "พร้อมหมายเลขเวอร์ชันและวันที่มีผลของตัวเอง",
