  "legal.terms.withTheSubjectLineArbitrationOptoutIfYouOptOutDisputesPr": "โดยมีหัวข้ออีเมล \"arbitration opt-out\" หากคุณปฏิเสธ ข้อพิพาทดำเนินการตาม section 20 และส่วนนี้ไม่มีผลกับคุณ",
