  "legal.terms.byAgreeingToArbitrationYouAndSophionosWaiveTheRightToATr": "ด้วยการตกลงเข้าร่วมอนุญาโตตุลาการ คุณและ SophionOS สละสิทธิในการพิจารณาคดีโดยผู้พิพากษาหรือคณะลูกขุนสำหรับข้อเรียกร้องที่อยู่ภายใต้ข้อตกลงทั้งหมด",
