  "legal.security.providersideEncryptionOnTheirStorageLayerPlusApplication": ": การเข้ารหัสฝั่งผู้ให้บริการบนชั้นจัดเก็บ บวกด้วยการเข้ารหัสระดับฟิลด์ของเนื้อหาส่วนตัวที่ชั้นแอปพลิเคชัน ใน SophionOS Cloud เนื้อหาบันทึก รายละเอียดผู้ติดต่อ และคำอธิบายกับลิงก์ที่บันทึกไว้บนพื้นที่ เป้าหมาย โปรเจกต์ งาน และทรัพยากรของคุณ ถูกเข้ารหัสด้วย AES-256-GCM ก่อนเขียนลงฐานข้อมูล เปิดใช้งานตลอดเวลาสำหรับทุกบัญชี Cloud และกุญแจไม่เคยถึงเบราว์เซอร์ นี่ไม่ใช่การเข้ารหัสแบบ end-to-end เซิร์ฟเวอร์ถือกุญแจ",
