  "legal.subprocessors.underIndiasDpdpAct2023TahaAalamSoleProprietorTradingAsSo": "ภายใต้ DPDP Act, 2023 ของอินเดีย Taha Aalam เจ้าของธุรกิจส่วนบุคคลที่ค้าขายภายใต้ชื่อ SophionOS เป็น Data Fiduciary และผู้ให้บริการเหล่านี้เป็น Data Processors ของเรา เมื่อ EU หรือ UK GDPR มีผลบังคับใช้ เราเป็นผู้ควบคุมข้อมูลและบริการเหล่านั้นเป็นผู้ประมวลผลของเรา แต่ละรายผูกพันตามสัญญาให้ประมวลผลข้อมูลส่วนตัวตามคำสั่งของเราและใช้มาตรการปกป้องด้านความปลอดภัย หน้านี้ระบุว่าพวกเขาเป็นใครและเหตุผลใด",
