  "legal.dataAndAi.andTurnOnAiSummariesInSettingsNotificationsWhenASchedule": "และเปิดสรุปโดย AI ใน ตั้งค่า → การแจ้งเตือน เมื่อสรุปประจำวันที่กำหนดไว้ถึงกำหนดและเปิดใช้งานอยู่ SophionOS จะส่งคำขอหนึ่งรายการไปยังผู้ให้บริการที่คุณเลือก ซึ่งมีข้อมูลตรงกับที่สรุปทางอีเมลมีอยู่แล้ว — จำนวนรายการ ชื่องานสำคัญ และชื่อเป้าหมายพร้อมความคืบหน้า ไม่มีการส่งอย่างอื่น ไม่มีฟีเจอร์อื่นเรียกโมเดล และหากผู้ให้บริการไม่พร้อมใช้งาน จะส่งสรุปแบบมาตรฐานแทน",
