  "legal.responsibleDisclosure.weAcknowledgeReportsWithin7DaysTellYouWhetherWeConsiderT": "เราตอบรับรายงานภายใน 7 days แจ้งว่าประเด็นอยู่ในขอบเขตหรือไม่ และอัปเดตความคืบหน้าให้คุณทราบ เราตั้งเป้าแก้ไขประเด็นร้ายแรงภายใน 30 days และประเด็นความรุนแรงต่ำภายใน 90 days และจะแจ้งหากต้องใช้เวลานานกว่า หน้าที่แจ้งการละเมิดใดๆ ตกกับผู้ดำเนินการอินสแตนซ์ที่ประเด็นนั้นส่งผลกระทบ ไม่ใช่ผู้รายงาน เรายินดีระบุชื่อคุณในบันทึกการแก้ไขหรือใน repository หากต้องการ เพียงบอกเรา",
